-- The driver's ASAP vehicle id (ASP-XX-XX), generated by the backend at driver setup for every
-- driver, bike or EV. license_number goes back to holding only the real licence.
ALTER TABLE back_drivers ADD COLUMN plate_number TEXT;
ALTER TABLE back_drivers ADD CONSTRAINT back_drivers_plate_number_key UNIQUE (plate_number);

-- Driver setup used to write the ASP id into license_number: move it across.
UPDATE back_drivers
   SET plate_number = license_number,
       license_number = NULL
 WHERE license_number ~ '^ASP-';
